// A copy shares the original's resource files: they are the coach's own uploads, and
// a learner reaches one only through a step that lists it (resourceLink).
(async () => {
  const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const id = String(Inputs.id || '');
    const found = id ? await Noodl.Records.query('LibraryItem', { objectId: { equalTo: id } }, { limit: 2, plain: true }) : [];
    if (found.length !== 1) return refuse('That homework is no longer in the library. Reload the page.');
    const src = found[0];
    const title = (String(Inputs.title || '').trim().replace(/\s+/g, ' ') || src.title || '').slice(0, 140);
    const row = await Noodl.Records.create('LibraryItem', {
      title,
      brief: src.brief || '',
      handInChecklist: Array.isArray(src.handInChecklist) ? src.handInChecklist : [],
      resources: Array.isArray(src.resources) ? src.resources : [],
      tags: Array.isArray(src.tags) ? src.tags : [],
      estimatedMinutes: typeof src.estimatedMinutes === 'number' ? src.estimatedMinutes : null,
      archived: false
    }, { plain: true });
    Outputs.id = row.objectId || row.id;
    Outputs.done();
  } catch (e) {
    console.error('[dbu:duplicateLibraryItem]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
